D = Direction
cur = [P(0, 0)]
def mv(q):
    if q.distance(cur[0]) > 6:
        move_to(q)
        cur[0] = q
def ins(q, drop_dir, proto=Prototype.Inserter):
    mv(q)
    try:
        i = place_entity(proto, direction=drop_dir, position=q)
    except Exception as e:
        print("ins err", q, str(e)[:120])
        return None
    dd = {D.UP: (0, -1), D.DOWN: (0, 1), D.LEFT: (-1, 0), D.RIGHT: (1, 0)}[drop_dir]
    for d in [D.UP, D.DOWN, D.LEFT, D.RIGHT, D.UP]:
        if abs(i.drop_position.x - q.x - dd[0]) < 0.6 and abs(i.drop_position.y - q.y - dd[1]) < 0.6:
            return i
        i = rotate_entity(i, d)
    print("INSERTER WRONG", q, i.pickup_position, i.drop_position)
    return i
def belt_run(pts, d):
    for q in pts:
        mv(q)
        try:
            place_entity(Prototype.TransportBelt, direction=d, position=q)
        except Exception as e:
            print("belt err", q, str(e)[:120])
def hline(y, x0, x1, d):
    s = 1 if x1 >= x0 else -1
    belt_run([P(x0 + k * s, y) for k in range(int(abs(x1 - x0)) + 1)], d)
def vline(x, y0, y1, d):
    s = 1 if y1 >= y0 else -1
    belt_run([P(x, y0 + k * s) for k in range(int(abs(y1 - y0)) + 1)], d)
def pole(x, y):
    mv(P(x, y))
    try:
        place_entity(Prototype.MediumElectricPole, position=P(x, y))
    except Exception as e:
        print("pole err", x, y, str(e)[:120])
def unit(fx, fy, outy, odir):
    mv(P(fx, fy))
    try:
        place_entity(Prototype.ElectricFurnace, position=P(fx, fy))
    except Exception as e:
        print("furn err", fx, fy, str(e)[:120])
    for dx, dd in [(-3, D.RIGHT), (3, D.LEFT)]:
        try:
            place_entity(Prototype.ElectricMiningDrill, position=P(fx + dx, fy), direction=dd)
        except Exception as e:
            print("drill err", fx + dx, fy, str(e)[:120])
    ins(P(fx, outy), odir)
def place_pair(ent, ex, d, alts, after):
    mv(ex)
    try:
        place_entity(Prototype.UndergroundBelt, direction=d, position=ent)
    except Exception as e:
        print("ent err", str(e)[:100])
    try:
        place_entity(Prototype.UndergroundBelt, direction=d, position=ex)
    except Exception as e:
        print("ex err", str(e)[:100])
    u = get_entity(Prototype.UndergroundBelt, ex)
    print("init", u.is_input, u.connected_to, u.direction)
    for a in alts:
        if (not u.is_input) and u.connected_to is not None:
            break
        try:
            u = rotate_entity(u, a)
        except Exception as e:
            print("rot err", str(e)[:100])
        u = get_entity(Prototype.UndergroundBelt, ex)
        print("rot", a, u.is_input, u.connected_to, u.direction)
    for (q, dd) in after:
        try:
            place_entity(Prototype.TransportBelt, direction=dd, position=q)
        except Exception as e:
            print("after err", str(e)[:100])
